[Form]
public class METSalesOrderShipmentListPage extends FormRun implements METIFormRefresh
{
    METShipmentDetailsForm  shipmentDetailsForm;
    METCustParameters       metCustParameters;

}

/// <summary>
/// Refresh method
/// </summary>
void refresh()
{        
    // Trigger execute query to refresh shipment status to loaded (multiselect)
    METShipmentTable_ds.executeQuery();
    METShipmentTable_ds.refresh();
}

    /// <summary>
    /// Enable buttons based on table fields values
    /// </summary>
    private void enableButtons()
    {
        // only possible to delete shipment when status is open
        METShipmentTable_ds.allowDelete(METShipmentTable.ShipmentStatus == WHSShipmentStatus::Open);

        // Enable Multimodal dangerous goods button only if customer group is the same as AR parameters
        HMIMMultimodalDGForm.enabled(CustGroup.CustGroup == metCustParameters.MultimodalDGCustGroup);

        // Confirm shipment button needs to remain active for shipments in open status.
        METSalesOrderShipmentConfirm.enabled(METShipmentTable.ShipmentStatus == WHSShipmentStatus::Open);

        // Post delivery note button needs to remain active for shipments in loaded status.
        METSalesOrderShipmentPackingSlipController.enabled(METShipmentTable.ShipmentStatus == WHSShipmentStatus::Loaded);
    }

    /// <summary>
    /// initialize form
    /// </summary>
    public void init()
    {
        shipmentDetailsForm = new METShipmentDetailsForm();

        super();
    }

        /// <summary>
        /// init datasource method
        /// </summary>
        public void init()
        {
            QueryBuildDataSource qbds;

            metCustParameters = METCustParameters::find();
            
            super();

            qbds = this.query().dataSourceTable(tableNum(METShipmentTable));

            // a default filter on shipment status field set to’ !Shipped’. This is to ensure the Despatch team only sees the pending shipments as a default view of this grid.
            qbds.addRange(fieldNum(METShipmentTable, ShipmentStatus)).value(SysQuery::valueNot(enum2int(WHSShipmentStatus::Shipped)));
        }

        /// <summary>
        /// active method, enable buttons based on current record
        /// </summary>
        /// <returns>Integer</returns>
        public int active()
        {
            int ret;
        
            ret = super();

            element.enableButtons();

            return ret;
        }

        /// <summary>
        /// Confirm shipment button needs to remain active if the shipments in a single load are selected for confirmation. This is to allow confirmation of all shipments in a load at once.
        /// The same logic to prevent shipment confirmation across loads (the button is to deactivate if shipments across loads are selected for confirmation).
        /// also adding logic if selected shipment status is not open, button is disabled
        /// </summary>
        public void markChanged()
        {
            METShipmentTable        METShipmentTableMarked;
            METLoadId               loadId;
            boolean                 sameLoadId = true;
            boolean                 openStatus = true, loadedStatus = true;
            MultiSelectionHelper    multiSelectionHelper =  MultiSelectionHelper::construct();
            multiSelectionHelper.parmDatasource(METShipmentTable_ds);
            METShipmentTableMarked = multiSelectionHelper.getFirst();
            
            loadId = METShipmentTableMarked.LoadId;
            openStatus = METShipmentTableMarked.ShipmentStatus == WHSShipmentStatus::Open;
            loadedStatus = METShipmentTableMarked.ShipmentStatus == WHSShipmentStatus::Loaded;
            
            while (METShipmentTableMarked)
            {         
                METShipmentTableMarked = multiSelectionHelper.getNext();

                if (METShipmentTableMarked && loadId != METShipmentTableMarked.LoadId)
                {
                    sameLoadId = false;
                    break;
                }

                if (METShipmentTableMarked && METShipmentTableMarked.ShipmentStatus != WHSShipmentStatus::Open)
                {
                    openStatus = false;
                }

                if (METShipmentTableMarked && METShipmentTableMarked.ShipmentStatus != WHSShipmentStatus::Loaded)
                {
                    loadedStatus = false;
                }
            }
            
            METSalesOrderShipmentConfirm.enabled(sameLoadId && openStatus);
            METSalesOrderShipmentPackingSlipController.enabled(sameLoadId && loadedStatus);

            super();
        }

        /// <summary>
        /// When clicking on transfer shipment to existing load button
        /// </summary>
        public void clicked()
        {
            super();

            if (shipmentDetailsForm.Transfer_clicked(METShipmentTable))
            {
                METShipmentTable_ds.research(true);
            }
        }

        /// <summary>
        /// When clicking on transfer shipment to new load button
        /// </summary>
        public void clicked()
        {
            super();

            if (shipmentDetailsForm.transferToNewLoad(METShipmentTable))
            {
                METShipmentTable_ds.research(true);
            }
        }
